/// The device proof a credential's headers carry (`x-better-iam-device`), or undefined when there is none or it is
/// not shaped like a compact JWS of at most 2048 characters. Headers normalize as for the bearer credential (a
/// `Headers` object, an array of pairs or a record); headers that cannot be read carry no proof.
/// The request header carrying a device proof (`deviceProofHeader`).
pub const DEVICE_PROOF_HEADER: &str = "x-better-iam-device";

pub fn device_proof_of(headers: Option<&[(String, String)]>) -> Option<String> {
    let headers = headers?;
    // `new Headers(init).get(name)`: every value of the name, joined with ", ".
    let values: Vec<&str> = headers
        .iter()
        .filter(|(name, _)| name.eq_ignore_ascii_case(DEVICE_PROOF_HEADER))
        .map(|(_, value)| value.as_str())
        .collect();
    if values.is_empty() {
        return None;
    }
    let value = values.join(", ");
    let segment = |part: &str| {
        !part.is_empty()
            && part
                .bytes()
                .all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-')
    };
    let parts: Vec<&str> = value.split('.').collect();
    (better_iam_core::js::utf16_len(&value) <= 2048
        && parts.len() == 3
        && parts.iter().all(|part| segment(part)))
    .then_some(value)
}

